def MemoryInWindow():
    # in-memory tasks (and pending acks) are exactly within (ackLevel, readLevel]
    if ack_level > read_level:
        return False
    for l in outstanding:
        if l <= ack_level or l > read_level:
            return False
    return True

def WindowComplete():
    # everything at-or-below readLevel is accounted for: a confirmed task
    # still in the DB and inside (ackLevel, readLevel] must be tracked in
    # outstandingTasks or held in newlyWrittenTasks — otherwise the reader
    # would never re-read it and it would never be dispatched.
    for t in confirmed:
        if t in db_tasks and t > ack_level and t <= read_level:
            if t not in outstanding and t not in newly_written:
                return False
    return True

def AckLevelOnlyPassesAcked():
    # if the ack level moved past a confirmed task, it must have been
    # acked or expired
    for t in confirmed:
        if t <= ack_level and t not in ever_acked and t not in expired:
            return False
    return True

def NoUnackedTaskDeleted():
    # a confirmed task can only leave the DB (GC) after being acked/expiring
    for t in confirmed:
        if t not in db_tasks and t not in ever_acked and t not in expired:
            return False
    return True

def ZombieRowExists():
    # a write timed out but was applied: unconfirmed row sits in the DB
    return writer_state == WS.IDLE and len([t for t in db_tasks if t not in confirmed]) > 0
